const bookedIds = $('Get Booked Equipment').all()
  .map(i => i.json.equipment_id)
  .filter(id => id != null);

const allEquipment = $('Get All Equipment').all().map(i => i.json);
const requested = $('Execute Workflow Trigger').first().json.requested_equipment || [];

const results = {
  available: [],
  unavailable: [],
  all_available: true
};

for (const reqName of requested) {
  const equip = allEquipment.find(e => e.name === reqName);
  if (!equip) {
    results.unavailable.push({ name: reqName, reason: 'Nerastas kataloge' });
    results.all_available = false;
    continue;
  }

  if (equip.status !== 'Available') {
    results.unavailable.push({
      name: reqName,
      icon: equip.icon,
      reason: `Statusas: ${equip.status}`
    });
    results.all_available = false;
    continue;
  }

  if (bookedIds.includes(equip.id)) {
    results.unavailable.push({
      name: reqName,
      icon: equip.icon,
      reason: 'Jau užsakytas šiai datai'
    });
    results.all_available = false;
    continue;
  }

  results.available.push({
    id: equip.id,
    name: equip.name,
    icon: equip.icon,
    category: equip.category,
    size_label: equip.size_label
  });
}

// Build Telegram message
let msg = '';
if (results.all_available) {
  msg = `✅ Visi laisvi ${$('Execute Workflow Trigger').first().json.event_date}:\n`;
  msg += results.available.map(e => `${e.icon} ${e.name}`).join('\n');
  msg += '\n\nPriskirti? [Taip] [Atšaukti]';
} else {
  msg = `⚠️ Nepakanka laisvų:\n`;
  if (results.available.length > 0) {
    msg += `Laisvi: ${results.available.map(e => `${e.icon} ${e.name}`).join(', ')}\n`;
  }
  msg += `Nelaisvi: ${results.unavailable.map(e => `${e.icon || '❌'} ${e.name} — ${e.reason}`).join('\n')}`;
}

results.telegram_message = msg;
return [{ json: results }];
